"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[52029],{96812:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponPoseEditorController","desc":"The weapon pose editor (`StarterGui.WeaponPoseGui`, both places). Opens on\\n`Signals.OpenWeaponPoseEditor` (the \\"Weapon Pose\\" button in the Settings GUI).\\nWhile open: movement is off, every other PlayerGui ScreenGui and the chat are hidden, an\\norbit camera circles the character (left/right-drag or touch-drag turns, middle-drag pans,\\nwheel or pinch zooms; the `Controls` box shows these)\\nwith the avatar left of the Panel, and the character holds a display copy of the picked\\nweapon (`EquipPoseDisplay`). Each slider change previews at once on this client\\n(`Signals.WeaponPosePreview`); Save sends the pose (`SaveWeaponPose`).\\nEach weapon is set on its own: scale, plus 18 offsets (two-hand) or the weapon position\\n(`WeaponPoseConfig.OneHand`). Reset = this weapon back to the built-in hold; Reset all and\\nClose with unsaved changes ask first (`Confirm`). Death, respawn or a hotbar key that\\nequips a real weapon closes at once and drops unsaved changes.","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponPoseEditorController.client.luau"}}')}}]);